sp_widget.css:
.encounters-list-container{
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: flex-start;
  align-items: center;
  column-gap: 1.5rem;

  .encounter-card{
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
    background-color: #000;
    padding: 2rem;
    border: .1rem solid #e21414;
    border-radius: 2rem;
    row-gap: .5rem;

    .card-header{
      display: flex;
      flex-direction: column;
      align-items: center;
      font-size: 1.6rem;
      font-weight: bold;
    }

    .card-body{
      display: flex;
      flex-direction: column;
      align-items: center;
    }
  }
}

sp_widget.script:
(function() {
  /* populate the 'data' object */
  /* e.g., data.table = $sp.getValue('table'); */
try{
	var util = new starWarsGMUtil();
	var campaignId = $sp.getParameter('campaign');
	data.encounters = util.getCampaignEncounters(campaignId);
	console.log(data.encounters);

	if(input){
		if(input.action == 'getEncounterDetails'){
			data.encounterDetails = util.getEncounterDetails(input.encounterID);
		}
	}
} catch(e){
	console.log('error in star wars encounter builder widget - server side: ' + e.message);
}
})();
